from sympy import *
vals={'76':76,'80':80,'84':84,'90':90}
# combined mean = (nA*70+nB*90)/(nA+nB) with nA>nB, i.e. strictly between 70 and 80
poss=set()
for nA in range(2,60):
    for nB in range(1,nA):
        poss.add(Rational(nA*70+nB*90,nA+nB))
m=[k for k,v in vals.items() if v in poss]
assert len(m)==1
result=m[0]

